const input = $input.first().json;

// El WhatsApp Trigger de n8n normalmente entrega contacts, messages y metadata
// en el nivel principal. Estas alternativas también admiten el webhook crudo de Meta.
const payload = input.body ?? input;
const value = payload.entry?.[0]?.changes?.[0]?.value ?? payload;
const message = value.messages?.[0] ?? input.messages?.[0] ?? {};
const contact = value.contacts?.[0] ?? input.contacts?.[0] ?? {};

const raw = String(
  message.text?.body ??
  message.interactive?.button_reply?.title ??
  message.interactive?.button_reply?.id ??
  message.interactive?.list_reply?.title ??
  message.interactive?.list_reply?.id ??
  input.chatInput ??
  input.message ??
  input.text ??
  ''
).trim();

// El teléfono del remitente se usa como identificador único de la conversación.
const waTo = String(
  message.from ??
  contact.wa_id ??
  input.waTo ??
  ''
).replace(/\D/g, '');

// ID del número empresarial que recibió el mensaje; se reutiliza para responder.
const businessPhoneNumberId = String(
  value.metadata?.phone_number_id ??
  input.metadata?.phone_number_id ??
  input.businessPhoneNumberId ??
  ''
);

const sessionId = String(
  waTo ||
  input.sessionId ||
  input.chatSessionId ||
  input.userId ||
  'demo-mercamio'
);


const normalize = (value = '') => String(value)
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();


const text = normalize(raw);
const store = $getWorkflowStaticData('global');
store.sessions ??= {};
let session = store.sessions[sessionId] ?? {
  step: 'inicio',
  data: {},
  startedAt: new Date().toISOString(),
};


const portal = 'https://mercamio.com.co/proveedores/';
const fieldLabels = {
  correo: 'correo electrónico',
  identificacion: 'número de identificación o NIT',
  numero_factura: 'número de la factura',
  comprobante: 'comprobante o número de radicación',
  tipo_certificado: 'tipo de certificado solicitado',
  valor_pagado: 'valor pagado',
  persona_contratante: 'nombre de la persona que contrató el servicio',
};


const routes = {
  CLI_RET: {
    userType: 'Cliente',
    category: 'Devolución de retenciones',
    owner: 'RUTA_CLI_RET@pendiente.local',
    sla: 'Por confirmar',
    required: ['correo'],
  },
  CLI_CAR: {
    userType: 'Cliente',
    category: 'Consulta de cartera',
    owner: 'Responsable de cartera por confirmar',
    sla: 'Por confirmar',
    required: ['identificacion', 'correo'],
  },
  PRO_PEN: {
    userType: 'Proveedor de mercancías',
    category: 'Factura pendiente',
    owner: 'RUTA_PRO_PEN@pendiente.local',
    sla: '2 días',
    required: ['identificacion', 'numero_factura', 'comprobante'],
  },
  PRO_CER: {
    userType: 'Proveedor de mercancías',
    category: 'Certificados',
    owner: 'RUTA_PRO_CER@pendiente.local',
    sla: 'Por confirmar',
    required: ['identificacion', 'tipo_certificado'],
  },
  ACR_DIF: {
    userType: 'Acreedor de servicios',
    category: 'Diferencia en valor pagado',
    owner: 'RUTA_ACR@pendiente.local',
    sla: '3 días',
    required: ['identificacion', 'numero_factura', 'valor_pagado'],
  },
  ACR_PEN: {
    userType: 'Acreedor de servicios',
    category: 'Factura pendiente',
    owner: 'Triage contabilidad - responsable por confirmar',
    sla: 'Por confirmar',
    required: ['identificacion', 'numero_factura', 'persona_contratante'],
  },
  ACR_CER: {
    userType: 'Acreedor de servicios',
    category: 'Certificados',
    owner: 'RUTA_ACR@pendiente.local',
    sla: 'Por confirmar',
    required: ['identificacion', 'tipo_certificado'],
  },
};


const menus = {
  Cliente: 'Selecciona tu solicitud:\n1. Devolución de retenciones\n2. Consulta de cartera',
  Proveedor: 'Selecciona tu solicitud:\n1. Pago cancelado\n2. Factura pendiente\n3. Certificados',
  Acreedor: 'Selecciona tu solicitud:\n1. Diferencia en valor pagado\n2. Factura pendiente\n3. Certificados\n4. Pago cancelado',
};


const yes = /^(1|si|sí|acepto|de acuerdo|confirmo)$/i.test(raw.trim());
const no = /^(2|no|no acepto|rechazo)$/i.test(raw.trim());
const validEmail = (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);


const save = () => {
  session.updatedAt = new Date().toISOString();
  store.sessions[sessionId] = session;
};


const startRoute = (code) => {
  const route = routes[code];
  session.routeCode = code;
  session.data.tipo_usuario = route.userType;
  session.data.categoria = route.category;
  session.pendingFields = [...route.required];
  session.currentField = session.pendingFields.shift();
  session.step = 'collecting';
  return 'Para continuar con ' + route.category + ', escribe tu ' + fieldLabels[session.currentField] + '.';
};


let output = '';
let action = 'RESPUESTA';
let ticket = null;


if (text === 'reiniciar' || text === 'nuevo') {
  session = { step: 'inicio', data: {}, startedAt: new Date().toISOString() };
}


if (session.step === 'inicio') {
  session.step = 'consentimiento';
  output = 'Hola, soy el asistente contable de MERCAMIO. Para atender tu solicitud necesitamos usar los datos que compartas únicamente para gestión y trazabilidad del caso. ¿Aceptas el tratamiento de datos?\n1. Sí, acepto\n2. No acepto';
} else if (session.step === 'consentimiento') {
  if (yes) {
    session.data.consentimiento = true;
    session.data.fecha_consentimiento = new Date().toISOString();
    session.step = 'nombre';
    output = 'Gracias. ¿Cuál es tu nombre completo?';
  } else if (no) {
    session.data.consentimiento = false;
    session.step = 'finalizado';
    action = 'CIERRE';
    output = 'Entendido. No solicitaremos más datos. Puedes comunicarte con el canal de atención definido por MERCAMIO. Escribe REINICIAR si deseas comenzar de nuevo.';
  } else {
    output = 'Por favor responde 1 para aceptar o 2 para no aceptar.';
  }
} else if (session.step === 'nombre') {
  if (raw.length < 2) {
    output = 'Escribe un nombre válido para continuar.';
  } else {
    session.data.nombre = raw;
    session.step = 'tipo_usuario';
    output = 'Gracias, ' + raw + '. ¿Qué tipo de usuario eres?\n1. Cliente\n2. Proveedor de mercancías\n3. Acreedor de servicios';
  }
} else if (session.step === 'tipo_usuario') {
  let userType = '';
  if (text === '1' || text.includes('cliente')) userType = 'Cliente';
  if (text === '2' || text.includes('proveedor')) userType = 'Proveedor';
  if (text === '3' || text.includes('acreedor')) userType = 'Acreedor';


  if (!userType) {
    output = 'Selecciona 1 Cliente, 2 Proveedor de mercancías o 3 Acreedor de servicios.';
  } else {
    session.data.tipo_usuario = userType;
    session.step = 'categoria';
    output = menus[userType];
  }
} else if (session.step === 'categoria') {
  const type = session.data.tipo_usuario;
  if (type === 'Cliente') {
    if (text === '1' || text.includes('retencion')) output = startRoute('CLI_RET');
    else if (text === '2' || text.includes('cartera')) output = startRoute('CLI_CAR');
    else output = menus.Cliente;
  } else if (type === 'Proveedor') {
    if (text === '1' || text.includes('pago cancelado')) {
      session.step = 'finalizado';
      action = 'CIERRE';
      output = 'Consulta el estado del pago en el portal de proveedores: ' + portal + '\nSi necesitas atención humana, escribe REINICIAR y selecciona nuevamente la categoría.';
    } else if (text === '2' || text.includes('factura')) {
      session.step = 'proveedor_radicacion';
      output = '¿La factura ya fue radicada?\n1. Sí\n2. No';
    } else if (text === '3' || text.includes('certificado')) {
      output = startRoute('PRO_CER');
    } else {
      output = menus.Proveedor;
    }
  } else if (type === 'Acreedor') {
    if (text === '1' || text.includes('diferencia')) output = startRoute('ACR_DIF');
    else if (text === '2' || text.includes('factura')) output = startRoute('ACR_PEN');
    else if (text === '3' || text.includes('certificado')) output = startRoute('ACR_CER');
    else if (text === '4' || text.includes('pago cancelado')) {
      session.step = 'finalizado';
      action = 'CIERRE';
      output = 'Consulta el estado del pago en el portal de proveedores: ' + portal + '\nEscribe REINICIAR para realizar otra solicitud.';
    } else {
      output = menus.Acreedor;
    }
  }
} else if (session.step === 'proveedor_radicacion') {
  if (yes) {
    output = startRoute('PRO_PEN');
  } else if (no) {
    session.step = 'finalizado';
    action = 'CIERRE';
    output = 'Primero debes radicar la factura siguiendo las indicaciones del portal: ' + portal + '\nEscribe REINICIAR cuando quieras iniciar una nueva consulta.';
  } else {
    output = 'Responde 1 si ya radicaste la factura o 2 si aún no la has radicado.';
  }
} else if (session.step === 'collecting') {
  const field = session.currentField;
  if (!raw) {
    output = 'El dato no puede estar vacío. Escribe tu ' + fieldLabels[field] + '.';
  } else if (field === 'correo' && !validEmail(raw)) {
    output = 'El correo no parece válido. Escríbelo nuevamente, por ejemplo: nombre@empresa.com';
  } else {
    session.data[field] = raw;
    if (session.pendingFields.length) {
      session.currentField = session.pendingFields.shift();
      output = 'Ahora escribe tu ' + fieldLabels[session.currentField] + '.';
    } else {
      const route = routes[session.routeCode];
      const ticketId = 'MCM-' + Date.now().toString().slice(-8);
      ticket = {
        ticket_id: ticketId,
        session_id: sessionId,
        fecha_creacion: new Date().toISOString(),
        estado: 'nuevo',
        responsable: route.owner,
        sla: route.sla,
        ruta: session.routeCode,
        ...session.data,
      };
      store.tickets ??= [];
      store.tickets.push(ticket);
      session.ticketId = ticketId;
      session.step = 'finalizado';
      action = route.owner.includes('por confirmar') ? 'ESCALAR' : 'TICKET';
      output = 'Solicitud registrada con el ticket ' + ticketId + '. Categoría: ' + route.category + '. Tiempo estimado: ' + route.sla + '. Escribe REINICIAR para crear otra solicitud.';
    }
  }
} else {
  output = 'Esta conversación ya terminó. Escribe REINICIAR para crear una nueva solicitud.';
  action = 'CIERRE';
}


save();


return [{
  json: {
    ...input,
    sessionId,
    waTo,
    businessPhoneNumberId,
    action,
    output,
    ticket,
    estado_sesion: session.step,
    ruta: session.routeCode ?? null,
  },
}];

const data = $input.first().json;
return [{ json: {
  output: data.output,
  action: data.action,
  sessionId: data.sessionId,
  waTo: data.waTo,
  businessPhoneNumberId: data.businessPhoneNumberId,
  estado_sesion: data.estado_sesion,
  ruta: data.ruta,
  ticket: data.ticket,
} }];
